// --- CONFIGURATION ---
u_min := 0;
u_max := 6.28318; // 2*PI
v_min := 0;
v_max := 6.28318;
steps := 350;

// --- SHADER CODE ---
// NB: do not declare variables named PI, pi, tau: the translator
// replaces them with the numeric value throughout the script.

// Geometric parameters
float a = 3.0; // Lemniscate amplitude
float r = 0.5; // Tube radius

// Curve: Gerono lemniscate in the z=0 plane.
// It passes through the origin TWICE (u = 0 and u = 3.14159): there the tube
// self-intersects.
vec3 Curve = vec3(
    a * sin(u),
    a * sin(u) * cos(u),
    0.0
);

// --- FIRST DERIVATIVE (analytic velocity) ---
vec3 dC = vec3(
    a * cos(u),
    a * cos(2.0 * u),
    0.0
);

vec3 Tangent = normalize(dC);

// --- STABLE FRAME COMPUTATION ---
// The curve lies in the z=0 plane: the tangent is never
// parallel to Z, so the frame never degenerates.
vec3 Up = vec3(0.0, 0.0, 1.0);
vec3 Binorm = normalize(cross(Tangent, Up));
vec3 Norm = normalize(cross(Binorm, Tangent));

// --- TUBE CONSTRUCTION ---
vec3 pos = Curve + r * (cos(v) * Norm + sin(v) * Binorm);

// Return the point in 4D (X, Y, Z, P)
return vec4(pos * 0.35, 0.0);

//CUTOUT_BEGIN
// Cut of the inner walls at the self-intersection point.
//
// BUG of the previous version: I assumed the crossing at u=0 could be
// resolved by comparing with the "mirrored" point u_mirror = -u on the SAME
// node. That is FALSE: the two arms touching at u=0 are the one LEAVING
// u=0 (toward the first quadrant) and the one ARRIVING at u=3.14159 (from
// the fourth quadrant) -- they are close in 3D SPACE but very far apart in
// the u parameter. The mirrored point -u was almost always too far in
// 3D space to be useful: the test almost never fired, leaving
// flaps of inner wall intact (visible as a residual ridge).
//
// FIX: when u is near a node (0 or 3.14159), we search for the true minimum
// distance by sampling AROUND BOTH nodes (not just the one closest
// to u), excluding only its own immediate neighborhood. Verified
// numerically: the test is symmetric (if a point of branch A falls
// inside branch B, the point ACTUALLY overlapping on branch B is
// cut as well) and stays confined to the true crossing zone (zero
// cuts away from the nodes).
float a2 = 3.0;
float r2 = 0.5;
float PI_2 = 3.14159265359;

// Activation: the test runs only if u is near a node (otherwise
// wasted cost away from the crossing).
float activateWindow = 0.5;
float dNode0 = min(abs(u), PI_2 * 2.0 - abs(u));
float dNodePi = abs(u - PI_2);
bool nearNode = (dNode0 < activateWindow) || (dNodePi < activateWindow);

bool didCut = false;

if (nearNode) {
    vec3 Curve2 = vec3(
        a2 * sin(u),
        a2 * sin(u) * cos(u),
        0.0
    );
    vec3 dC2 = vec3(
        a2 * cos(u),
        a2 * cos(2.0 * u),
        0.0
    );
    vec3 Tangent2 = normalize(dC2);
    vec3 Up2 = vec3(0.0, 0.0, 1.0);
    vec3 Binorm2 = normalize(cross(Tangent2, Up2));
    vec3 Norm2 = normalize(cross(Binorm2, Tangent2));
    vec3 pos2 = Curve2 + r2 * (cos(v) * Norm2 + sin(v) * Binorm2);

    // 2026-07-21: the light/dark patches and jagged edges at the
    // seam were SAMPLING NOISE: 24 samples over a
    // 1.0 rad window estimate the minimum with error up to ~0.008
    // (almost 2% of r2), so along the seam the test kept or
    // cut fragments at random: flaps kept by mistake coincide
    // in depth with the other branch (z-fight -> patches) and the
    // cut edge wobbles (jagged). Fix in two moves:
    // 1) search only around the OTHER branch's node: u is already
    //    near a node, and the branch that can touch this point is
    //    always the other node's, never its own (verified
    //    numerically: its own branch stays at distance > 0.8).
    //    excludeSelf disappears too.
    // 2) coarse scan (24 samples) + 5 Newton steps on the
    //    true minimum: measured error 7e-8 (was 8e-3).
    // The threshold stays the original SYMMETRIC one (r2 on both branches):
    // with the precise distance no asymmetries are needed, which at the
    // tangencies (0,0,+/-r) opened holes (red areola).
    float otherNode = (dNode0 < dNodePi) ? PI_2 : 0.0;

    float bestU = otherNode;
    float bestDist = 1000.0;
    for (float k = 0.0; k < 24.0; k = k + 1.0) {
        float u2 = otherNode - 0.5 + k / 23.0;
        vec3 c2 = vec3(a2 * sin(u2), a2 * sin(u2) * cos(u2), 0.0);
        float d = length(pos2 - c2);
        if (d < bestDist) { bestDist = d; bestU = u2; }
    }

    // Newton on g(u2) = dot(pos2 - C(u2), C'(u2)) = 0
    float uN = bestU;
    for (float it = 0.0; it < 5.0; it = it + 1.0) {
        vec3 cN = vec3(a2 * sin(uN), a2 * sin(uN) * cos(uN), 0.0);
        vec3 t1 = vec3(a2 * cos(uN), a2 * cos(2.0 * uN), 0.0);
        vec3 t2 = vec3(-a2 * sin(uN), -2.0 * a2 * sin(2.0 * uN), 0.0);
        vec3 w = pos2 - cN;
        float g = dot(w, t1);
        float gp = dot(w, t2) - dot(t1, t1);
        if (abs(gp) > 0.000001) { uN = uN - g / gp; }
        uN = clamp(uN, otherNode - 0.55, otherNode + 0.55);
    }
    vec3 cB = vec3(a2 * sin(uN), a2 * sin(uN) * cos(uN), 0.0);
    bestDist = min(bestDist, length(pos2 - cB));

    didCut = (bestDist < r2);
}

return didCut;
//CUTOUT_END
